      p2: 'Nós os agrupamos em três categorias: <b>estritamente necessários</b> (sempre ativos, porque o login e o site não funcionam sem eles), <b>funcionais</b> (lembram suas preferências neste dispositivo), e <b>análise e atribuição</b> (creditam um parceiro que indicou você). O armazenamento funcional e de atribuição fica desligado até você permiti-los.',
